/bin/zsh -lc "python -c \"import numpy as np,pandas as pd; from scipy.optimize import minimize; from scipy.special import expit; d=pd.read_csv('data/nls_ses_processed.csv'); x=d.SES.to_numpy(); y=d['BA DEGREE COMPLETED'].astype(float).to_numpy(); X=np.c_[np.ones(len(x)),x]; p=y.mean(); b=np.array([np.log(p/(1-p)),0.]); f=lambda z:(float(np.sum(np.logaddexp(0,X@z)-y*(X@z))), X.T@(expit(X@z)-y));
for m in ['BFGS','L-BFGS-B']:
 r=minimize(f,b,jac=True,method=m,options={'gtol':1e-8,'maxiter':1000}); print(m,r.success,r.message,r.x,r.jac,r.fun,r.nit)\""

